var calc_output = [];

var care = parseFloat(care);
var indoor = parseFloat(indoor);
var level = parseFloat(level);
var climb = parseFloat(climb);
var run = parseFloat(run);
var lightwork = parseFloat(lightwork);
var modwork = parseFloat(modwork);
var heavywork = parseFloat(heavywork);
var yard = parseFloat(yard);
var sex = parseFloat(sex);
var modac = parseFloat(modac);
var strenac = parseFloat(strenac);

var u = care + indoor + level + climb + run + lightwork + modwork + heavywork + yard + sex + modac + strenac;
var msg = 'The higher the score (maximum 58.2), the higher the functional status.';
var mini_msg = 'Maximum score is 58.2';
var mets = (0.43 * u + 9.6) / 3.5

calc_output.push({ 
	name: 'mini', 
	value: u, 
	value_text: 'points', 
	message: mini_msg 
});
calc_output.push({ 
	name: '3910_DASI_result (score)', 
	value: u, 
	value_text: 'points', 
	message: msg 
});
calc_output.push({ 
	name: '3910_DASI_result (METs)',
	value: mets.toFixed(2), 
	value_text: 'METs', 
	message: '' 
});
